const getRequiredPoints=(shortName,course)=>{const u=UNIVERSITIES_DATA.find(x=>x.shortName===shortName);return u?.courses[course]?.minPoints||13;};
const getPreferredSubjects=(shortName,course)=>{const u=UNIVERSITIES_DATA.find(x=>x.shortName===shortName);return u?.courses[course]?.combination||[];};
const getUnisForCourse=course=>UNIVERSITIES_DATA.filter(u=>u.acceptsJUPEB&&u.courses[course]);
const getTierLabel=tier=>tier===1?"🔥 Elite Federal":tier===2?"⭐ State Universities":"🏛️ Private Universities";
const searchUniversities=(query,courseFilter=null)=>{
  const q=(query||"").trim().toLowerCase();
  return UNIVERSITIES_DATA.filter(u=>{
    if(!q)return true;
    return(
      u.name.toLowerCase().includes(q)||
      u.shortName.toLowerCase().includes(q)||
      u.location.toLowerCase().includes(q)||
      (u.state||"").toLowerCase().includes(q)||
      (u.searchAliases||[]).some(a=>a.toLowerCase().includes(q))
    );
  }).sort((a,b)=>{
    // Course-matching universities come first
    const aMatch=courseFilter?!!a.courses[courseFilter]:true;
    const bMatch=courseFilter?!!b.courses[courseFilter]:true;
    if(aMatch&&!bMatch)return -1;
    if(!aMatch&&bMatch)return 1;
    return(a.popularRank||99)-(b.popularRank||99);
  });
};
const IDB = {
  _db: null,
  async open() {
    if (this._db) return this._db;
    return new Promise((res, rej) => {
      const req = indexedDB.open("crediq_v1", 1);
      req.onupgradeneeded = e => { e.target.result.createObjectStore("cache", { keyPath:"key" }); };
      req.onsuccess = e => { this._db = e.target.result; res(this._db); };
      req.onerror = () => rej(req.error);
    });
  },
  async get(key) {
    try {
      const db = await this.open();
      return new Promise(res => {
        const req = db.transaction("cache","readonly").objectStore("cache").get(key);
        req.onsuccess = () => {
          const r = req.result;
          // Bumped from 24h to 7 days — questions change rarely (new ones added
          // occasionally, not constantly), and this cache is the single biggest
          // lever on Firestore read volume: a full re-fetch of a subject's
          // question bank is hundreds to low-thousands of document reads, and
          // that was happening for every student once per day. At 460+ students,
          // even a modest fraction re-fetching on the same day can blow through
          // the entire 50,000/day free-tier quota on its own — which is what
          // caused today's ~14hr outage. A student will now go up to a week
          // between full refetches instead of one day.
          res(r && Date.now()-r.ts < 7*24*60*60*1000 ? r.data : null);
        };
        req.onerror = () => res(null);
      });
    } catch { return null; }
  },
  async set(key, data) {
    try {
      const db = await this.open();
      return new Promise(res => {
        const tx = db.transaction("cache","readwrite");
        tx.objectStore("cache").put({ key, data, ts:Date.now() });
        tx.oncomplete = () => res(true);
        tx.onerror = () => res(false);
      });
    } catch { return false; }
  }
};

// ─── STREAK SYSTEM (localStorage) ────────────────────────────────────────────
const Streak = {
  get() {
    const _uid=localStorage.getItem("cq_current_uid")||"anon";
    const last = localStorage.getItem("cq_sd_"+_uid);
    const count = parseInt(localStorage.getItem("cq_sc_"+_uid) || "0");
    const today = new Date().toDateString();
    const yesterday = new Date(Date.now()-86400000).toDateString();
    if (last === today) return { count, studiedToday:true };
    if (last === yesterday) return { count, studiedToday:false };
    return { count:0, studiedToday:false };
  },
  bump() {
    const today = new Date().toDateString();
    const { count, studiedToday } = this.get();
    const newCount = studiedToday ? count : count+1;
    const _uid2=localStorage.getItem("cq_current_uid")||"anon";
    localStorage.setItem("cq_sd_"+_uid2, today);
    localStorage.setItem("cq_sc_"+_uid2, String(newCount));
    return newCount;
  }
};

// ─── SESSION PROTECTION (localStorage only tonight — wire to Firestore tmrw) ──
const Session = {
  generate() {
    const id = Math.random().toString(36).slice(2) + Date.now().toString(36);
    localStorage.setItem("cq_session_id", id);
    return id;
  },
  get() { return localStorage.getItem("cq_session_id"); },
  clear() { localStorage.removeItem("cq_session_id"); }
};

// ─── DRILL CAP — free users get 5 drill sessions per week ────────────────────
const DrillCap={
  KEY:"cq_drill_week_",
  getMonday(){
    const d=new Date();d.setHours(0,0,0,0);
    const day=d.getDay();
    d.setDate(d.getDate()-(day===0?6:day-1));
    return d.toDateString();
  },
  get(uid){
    try{
      const raw=localStorage.getItem(this.KEY+uid);
      if(!raw)return{count:0,week:this.getMonday()};
      const data=JSON.parse(raw);
      if(data.week!==this.getMonday())return{count:0,week:this.getMonday()};
      return data;
    }catch{return{count:0,week:this.getMonday()};}
  },
  increment(uid){
    const data=this.get(uid);
    const updated={count:data.count+1,week:this.getMonday()};
    try{localStorage.setItem(this.KEY+uid,JSON.stringify(updated));}catch{}
    return updated.count;
  },
  check(uid){
    const data=this.get(uid);
    return{used:data.count,remaining:Math.max(0,5-data.count),allowed:data.count<5};
  }
};

