const getFuture = c => FUTURES[c]||"Graduate";
const getGreet = () => { const h=new Date().getHours(); if(h>=22||h<4)return"Still at it,"; return h<12?"Good morning":h<17?"Good afternoon":"Good evening"; };
const grade = pct => pct>=70?"A":pct>=60?"B":pct>=50?"C":pct>=45?"D":"F";
const shareGrade = pct => pct>=90?"A+":pct>=70?"A":pct>=60?"B":pct>=50?"C":pct>=45?"D":"F";
const gradeColor = (g,T) => g==="A"?T.success:g==="B"?T.gold:(g==="C"||g==="D")?T.warn:T.danger;
const makeRef = uid => "CQ"+uid.slice(0,6).toUpperCase();

function daysUntil(dateStr) {
  const target = new Date(dateStr);
  const now = new Date();
  target.setHours(0,0,0,0); now.setHours(0,0,0,0);
  return Math.max(0, Math.ceil((target-now)/(1000*60*60*24)));
}

function getNextExam(userSubjects) {
  const today = new Date(); today.setHours(0,0,0,0);
  for (const entry of JUPEB_TIMETABLE) {
    const d = new Date(entry.date); d.setHours(0,0,0,0);
    if (d >= today && entry.subjects.some(s => userSubjects.includes(s))) {
      return { ...entry, days: Math.ceil((d-today)/(1000*60*60*24)) };
    }
  }
  return null;
}

function calcMastery(history, subject) {
  const relevant = history.filter(h=>h.subject===subject);
  if (!relevant.length) return 0;
  const avg = recentSubjectAccuracy(relevant);
  return Math.min(95, Math.round(avg*0.85 + Math.min(relevant.length*2,15)));
}

const STEM_SUBJECTS=["Physics","Chemistry","Mathematics","Biology","Economics","Geography","Agriculture","English"];
const RELIGIOUS_TERMS=["jahiliyyah","prophet","muhammad","quran","allah","islamic","madinah","makkah","mecca","medina","hadith","sunnah","caliphate","hijra","ukaz","taif","arafah","mosque","siffin","khadijah","uthman","abubakar","imam bukhari","nawawi","surah","umrah","hajj","salat","zakat","tawhid","shirk","aqeedah","baptism","crucifixion","apostle","genesis","exodus","deuteronomy","leviticus","old testament","new testament","holy ghost","holy spirit","ten commandments","passover","resurrection of","sermon on the mount"];
// Normalizes an answer key before comparison so formatting drift in question-bank
// data (case, whitespace, stray punctuation like "A." or "a)") never silently
// marks a genuinely correct answer as wrong.
function normAnswerKey(a){
  if(a===undefined||a===null)return "";
  const s=String(a).trim().toUpperCase();
  const m=s.match(/^([A-D])/); // grab leading option letter if present amid punctuation
  return m?m[1]:s;
}
function answersMatch(userAnswer,correctAnswer){
  return normAnswerKey(userAnswer)===normAnswerKey(correctAnswer);
}

// ─── SEMANTIC MISMATCH DETECTION ───────────────────────────────────────────────
// Catches what the structural audit can't: correctAnswer points to a REAL
// option key, but the wrong one — usually because option order got shuffled
// during question-bank upload without correctAnswer being remapped to follow.
const STOPWORDS=new Set(["the","a","an","is","was","were","are","of","in","on","at","to","and","or",
  "but","by","with","for","as","that","this","these","those","it","its","his","her","their","he","she",
  "they","which","who","whom","from","be","been","being","not","no","so","if","then","than","because",
  "due","during","after","before","when","where","what","how","why","did","do","does","having","has",
  "had","will","would","should","could","can","may","might","one","also","such","into","over","under"]);

function stem(w){
  // basic singular/plural normalization — "sandals"→"sandal", "kings"→"king"
  if(w.length>4&&w.endsWith("es"))return w.slice(0,-2);
  if(w.length>3&&w.endsWith("s")&&!w.endsWith("ss"))return w.slice(0,-1);
  return w;
}
function tokenize(text){
  return(text||"").toLowerCase().replace(/[^a-z0-9\s]/g," ").split(/\s+/)
    .filter(w=>w.length>=3&&!STOPWORDS.has(w)).map(stem);
}
// Coverage = what fraction of THIS option's own words appear in the explanation.
// Using coverage instead of a raw count means short options (many quiz options
// are a single word like "Sandal" or "Staff") can still score a clean 100%
// match instead of being unfairly penalized against longer options.
// Word-overlap scoring only works for prose-style answers ("Sandal", "Federalism").
// It breaks on numbers, currency, and short technical codes — a single garbled
// character ("₦12,418" → "W12418") or a missing space ("IAS2" vs "IAS 2") is
// enough to flip the result, and numbers merely MENTIONED in an explanation's
// working (e.g. an input value) can outscore the actual computed answer.
// So: skip the semantic check entirely when most of a question's options look
// numeric/currency/code-like — that's a different problem needing a different
// tool (recomputing the answer, not comparing words), not something we should
// guess at with prose-matching.
function looksNumericOrCode(text){
  const s=String(text||"").trim();
  if(!s)return true;
  if(/^[₦$#]?[\d,]+(\.\d+)?%?$/.test(s))return true;       // ₦12,418 · 20,000 · 10% · 648
  if(/^[A-Za-z]{1,6}[\s-]?\d{1,6}$/.test(s))return true;    // IAS2 · IAS 15 · IFRS 9 · M648 · W12418
  if(s.replace(/[^0-9]/g,"").length/Math.max(1,s.length)>0.4)return true; // digit-heavy strings
  return false;
}

// ─── NUMERIC ANSWER CHECKER ─────────────────────────────────────────────────
// Two different techniques for the two ways numeric/code answers break —
// word-overlap can't handle either one, so this isn't a variant of that check,
// it's a separate tool:
//
// A) CURRENCY/NUMBER options → find the LAST "= <number>" in the explanation
//    (the final computed result in a step-by-step working) and compare
//    DIGITS ONLY — this survives OCR corruption too, since "₦12,418" stored
//    as "W12418" still normalizes to the same digit string "12418".
// B) CODE-STYLE options ("IAS2", "IAS 15") → strip ALL whitespace from both
//    the option and the explanation, then check literal substring containment
//    — this survives spacing differences that break word-tokenization
//    ("IAS2" vs "IAS 2" look identical once spaces are stripped).
//
// Both are deliberately conservative: ambiguous cases return null (skip)
// rather than force a guess.
function isCurrencyOrNumber(s){
  const t=String(s||"").trim();
  if(/^[₦$#]?[\d,]+(\.\d+)?%?$/.test(t))return true;       // clean: ₦12,418 · 20,000 · 10%
  if(/^[A-Za-z][\d,]{3,}$/.test(t))return true;             // 1 garbled currency symbol + 3+ digit amount: W12418 · M648
  return false;
}
function isCodeLike(s){
  return/^[A-Za-z]{2,6}[\s-]?\d{1,6}$/.test(String(s||"").trim()); // real codes need 2+ letters: IAS2 · IAS 15 · IFRS 9
}
function digitsOnly(s){return String(s||"").replace(/[^\d]/g,"");}
function compactAlnum(s){return String(s||"").toLowerCase().replace(/[^a-z0-9]/g,"");}

function extractFinalComputedNumber(text){
  const matches=[...String(text||"").matchAll(/=\s*[₦$#]?\s*[\d][\d,]*\.?\d*%?/g)];
  if(!matches.length)return null;
  const last=matches[matches.length-1][0];
  const digits=digitsOnly(last);
  return digits.length?digits:null;
}

function checkNumericMismatch(q,ca){
  const entries=Object.entries(q.options);
  if(!entries.length)return null;
  const allCurrency=entries.every(([,v])=>isCurrencyOrNumber(v));
  const allCode=entries.every(([,v])=>isCodeLike(v));

  if(allCurrency){
    const target=extractFinalComputedNumber(q.explanation);
    if(!target)return null;
    const matches=entries.filter(([,v])=>digitsOnly(v)===target);
    if(matches.length!==1)return null; // ambiguous or nothing matched exactly — don't guess
    const[bestKey]=matches[0];
    if(normAnswerKey(bestKey)===ca)return null; // already correct
    return{suggestedKey:bestKey,method:"Computed value",evidence:`Explanation computes to ${target}`};
  }

  if(allCode){
    const compactExp=compactAlnum(q.explanation);
    if(compactExp.length<10)return null; // too little explanation text to trust
    const matches=entries.filter(([,v])=>{const c=compactAlnum(v);return c.length>=3&&compactExp.includes(c);});
    if(matches.length!==1)return null; // ambiguous — 0 or 2+ codes found verbatim in explanation
    const[bestKey]=matches[0];
    if(normAnswerKey(bestKey)===ca)return null;
    return{suggestedKey:bestKey,method:"Code match",evidence:`"${q.options[bestKey]}" appears in the explanation`};
  }

  return null; // mixed option types — too ambiguous to auto-check
}

// ─── THEORY CONTENT AUDIT ────────────────────────────────────────────────────
// The MCQ answer-key audit above requires q.options and skips everything else —
// meaning theoryQuestions has NEVER actually been scanned by anything. This
// catches the three ways a theory question breaks in a way that's invisible
// until a student hits it live:
//   1. Empty question text — the student sees nothing to answer.
//   2. No gradable model answer anywhere (main answer AND every subQuestion
//      answer are empty) — self-mark reveal has nothing to show, AI grading
//      has nothing to compare against.
//   3. Question text that's mostly raw numeric/table data with no
//      instructional verb — a data table got stored as if it WERE the
//      question, instead of being reference material attached to one.
function checkTheoryContentIssues(q){
  const issues=[];
  const qt=(q.question||"").trim();
  if(!qt){
    issues.push("Empty question text");
  }else{
    const nonSpace=qt.replace(/\s/g,"");
    const digitLike=(qt.match(/[\d.,]/g)||[]).length;
    const digitRatio=nonSpace.length?digitLike/nonSpace.length:0;
    const hasInstructionVerb=/\b(calculate|find|determine|using|given|state|explain|define|describe|evaluate|solve|show|prove|derive|compute|what|why|how|discuss|list|outline|identify|compare|analyse|analyze|write|draw|sketch|name|give|distinguish|differentiate|illustrate|account|justify)\b/i.test(qt);
    if(digitRatio>0.55&&qt.length>15&&!hasInstructionVerb){
      issues.push("Looks like raw data/table with no instruction");
    }
  }
  const mainAnswerEmpty=!q.answer||!String(q.answer).trim();
  const subAnswers=(q.subQuestions||[]).map(sq=>sq.answer);
  const hasAnySubAnswer=subAnswers.some(a=>a&&String(a).trim());
  if(mainAnswerEmpty&&!hasAnySubAnswer){
    issues.push("No gradable model answer found");
  }
  return issues;
}

function optionCoverage(explanationTokenSet,optionText){
  const optTokens=tokenize(optionText);
  if(!optTokens.length)return 0;
  let matched=0;
  optTokens.forEach(t=>{if(explanationTokenSet.has(t))matched++;});
  return matched/optTokens.length; // 0..1 — fraction of this option's words found in the explanation
}
function isUsableQuestion(q){
  if(q.hasDiagram===true&&!q.diagramUrl)return false;
  if(STEM_SUBJECTS.includes(q.subject||"")){
    const text=(q.question||q.text||q.q||"").toLowerCase();
    const topic=(q.topic||q.subtopic||"").toLowerCase();
    const allText=text+" "+topic;
    if(RELIGIOUS_TERMS.some(kw=>allText.includes(kw)))return false;
    // Also filter by topic name directly
    if(topic.includes("quran")||topic.includes("islamic")||topic.includes("irs")||topic.includes("christian")||topic.includes("bible")||topic.includes("crs"))return false;
  }
  return true;
}
function getAllQuestionsForSubject(QB,subject) {
  if (!QB[subject]) return [];
  return Object.values(QB[subject]).flat().filter(isUsableQuestion);
}
// Looks a set of question ids up across every subject in QB, regardless of
// which subject/year config produced them originally — used to rebuild an
// interrupted session's exact question set from just its ids.
function findQuestionsByIds(QB,ids){
  if(!ids||!ids.length)return[];
  const byId={};
  Object.keys(QB).forEach(subj=>{
    getAllQuestionsForSubject(QB,subj).forEach(q=>{if(q.id!=null&&byId[q.id]===undefined)byId[q.id]=q;});
  });
  return ids.map(id=>byId[id]).filter(Boolean);
}

// ─── Interrupted-session recovery (localStorage) ──────────────────────────
// A practice/exam session is saved after every answer/navigation so closing
// the app mid-session (not just backgrounding it) doesn't lose progress.
const RESUME_SESSION_KEY="crediq_resume_session_v1";
const RESUME_SESSION_MAX_AGE_MS=12*60*60*1000; // 12h — older than this, treat as stale
const RESUME_AUTO_THRESHOLD_MS=30*60*1000; // 30min — under this, resume silently instead of asking
function saveResumeSnapshot(snap){
  try{localStorage.setItem(RESUME_SESSION_KEY,JSON.stringify(snap));}catch{}
}
function loadResumeSnapshot(){
  try{const raw=localStorage.getItem(RESUME_SESSION_KEY);return raw?JSON.parse(raw):null;}catch{return null;}
}
function clearResumeSnapshot(){
  try{localStorage.removeItem(RESUME_SESSION_KEY);}catch{}
}
function getQuestions(QB,subject,year) {
  const qs=(QB[subject]&&QB[subject][String(year)]) ? QB[subject][String(year)] : [];
  return qs.filter(isUsableQuestion);
}
function getMixedExam(QB,subjects,count=50) {
  let pool=[];
  subjects.forEach(sub=>getAllQuestionsForSubject(QB,sub).forEach(q=>pool.push({...q,subject:sub})));
  for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}
  return pool.slice(0,count);
}
function getQuestionsForDrill(QB,subjects,weakTopics,count=10) {
  let pool=[];
  subjects.forEach(sub=>{
    getAllQuestionsForSubject(QB,sub).forEach(q=>{
      if(!weakTopics.length||weakTopics.some(t=>q.topic&&q.topic.toLowerCase().includes(t.toLowerCase().split(" ")[0])))
        pool.push({...q,subject:sub});
    });
  });
  if(pool.length<count) subjects.forEach(sub=>getAllQuestionsForSubject(QB,sub).forEach(q=>pool.push({...q,subject:sub})));
  const seen=new Set();
  pool=pool.filter(q=>{const k=q.subject+q.id;if(seen.has(k))return false;seen.add(k);return true;});
  for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}
  return pool.slice(0,count);
}
function calcReadiness(history) {
  const clean=history.filter(isRealSession);
  if(!clean.length)return 0;
  const r=clean.slice(-10);
  return Math.round((r.reduce((s,h)=>s+h.pct,0)/r.length*0.7)+(Math.min(100,r.length*10)*0.3));
}
function calcWeakTopics(history) {
  // Returns plain topic strings (backward compat)
  return calcTopicStatus(history).weak.map(x=>typeof x==="string"?x:x.t);
}
// New: returns [{t, score, subject}] with subject attached
function calcWeakTopicsWithSubject(history) {
  return calcTopicStatus(history).weak;
}
// CLEAN_SUBJECTS: sessions that count toward real JUPEB subject tracking
const JUNK_SUBJECTS=["Mixed","Drill","Random Warm-Up","Random Practice",""];
// Theory sessions are excluded here — they have no pct/correct/total, only wrongTopics,
// so they must never enter accuracy-averaging code (calcSubjectStats, calcReadiness, calcStudyTime).
// calcTopicStatus below uses its own broader filter so Theory still contributes weak topics.
const isRealSession=h=>h.subject&&!JUNK_SUBJECTS.includes(h.subject)&&h.mode!=="Theory";

function calcSubjectStats(history) {
  const s={};
  history.filter(isRealSession).forEach(h=>{
    const k=h.subject;
    if(!s[k])s[k]={sessions:0,totalPct:0,best:0,totalDuration:0,lastDate:null};
    s[k].sessions++;
    s[k].totalPct+=h.pct;
    s[k].best=Math.max(s[k].best,h.pct);
    s[k].totalDuration+=(h.duration||0);
    const d=h.date||new Date().toISOString();
    if(!s[k].lastDate||d>s[k].lastDate)s[k].lastDate=d;
  });
  return s;
}
function calcStudyTime(history) {
  return Math.round(history.filter(isRealSession).reduce((s,h)=>s+(h.duration||0),0)/60);
}

// ─── PHASE 3: LEARNING SCIENCE ────────────────────────────────────────────────
function calcReadinessTrend(history) {
  if(history.length<2)return{points:[],delta:0,monthDelta:0};
  const size=Math.max(1,Math.floor(history.length/6));
  const points=[];
  for(let i=0;i<history.length;i+=size){
    const chunk=history.slice(i,i+size);
    points.push({score:Math.round(chunk.reduce((s,h)=>s+h.pct,0)/chunk.length)});
  }
  const delta=points.length>=2?points[points.length-1].score-points[0].score:0;
  const recent=history.slice(-Math.min(10,Math.ceil(history.length/2)));
  const older=history.slice(0,Math.min(10,Math.floor(history.length/2)));
  const monthDelta=older.length&&recent.length
    ?Math.round(recent.reduce((s,h)=>s+h.pct,0)/recent.length-older.reduce((s,h)=>s+h.pct,0)/older.length)
    :0;
  return{points,delta,monthDelta};
}
function calcReviewQueue(history) {
  const clean=history.filter(isRealSession);
  if(!clean.length)return[];
  const topicMap={};
  clean.forEach(h=>{
    const d=h.date||new Date().toISOString();
    (h.wrongTopics||[]).filter(t=>t&&t!=="Uncategorized").forEach(t=>{
      if(!topicMap[t])topicMap[t]={wrong:0,lastDate:d,subject:h.subject||""};
      topicMap[t].wrong++;
      if(d>topicMap[t].lastDate)topicMap[t].lastDate=d;
      if(!topicMap[t].subject&&h.subject)topicMap[t].subject=h.subject;
    });
  });
  const today=new Date();today.setHours(0,0,0,0);
  return Object.entries(topicMap).map(([topic,data])=>{
    const interval=data.wrong>=5?1:data.wrong>=3?2:data.wrong>=2?3:7;
    const last=new Date(data.lastDate);last.setHours(0,0,0,0);
    const daysSince=Math.max(0,Math.floor((today-last)/86400000));
    return{topic,wrong:data.wrong,dueIn:interval-daysSince,interval,subject:data.subject};
  }).filter(t=>t.dueIn<=0).sort((a,b)=>a.dueIn-b.dueIn).slice(0,5);
}
function calcTopicImprovement(history) {
  if(history.length<4)return[];
  const mid=Math.ceil(history.length/2);
  const rate=(sessions,topic)=>{
    const count=sessions.filter(h=>(h.wrongTopics||[]).includes(topic)).length;
    return sessions.length?Math.round((count/sessions.length)*100):0;
  };
  const older=history.slice(0,mid),recent=history.slice(mid);
  const allTopics=[...new Set(history.flatMap(h=>h.wrongTopics||[]))];
  return allTopics.map(t=>{
    const oldRate=rate(older,t),newRate=rate(recent,t);
    const delta=oldRate-newRate; // positive = fewer wrong = improvement
    return{topic:t,oldRate,newRate,delta};
  }).filter(t=>Math.abs(t.delta)>=10).sort((a,b)=>b.delta-a.delta).slice(0,6);
}
function calcTopicStatus(history) {
  // Broader than isRealSession on purpose — Theory sessions (mode:"Theory") only ever
  // carry subject + wrongTopics, no pct, so they're safe to include here for weak-topic
  // detection even though they're excluded from accuracy-averaging functions elsewhere.
  const clean=history.filter(h=>h.subject&&!JUNK_SUBJECTS.includes(h.subject));
  if(!clean.length)return{weak:[],improving:[],graduated:[],topicSubjectMap:{}};
  const recent5=clean.slice(-5);
  const older=clean.length>5?clean.slice(0,-5):[];
  const count=(sessions,topic)=>sessions.filter(h=>(h.wrongTopics||[]).includes(topic)).length;
  // Track which subject each topic came from
  const topicSubjectMap={};
  clean.forEach(h=>(h.wrongTopics||[]).forEach(t=>{if(!topicSubjectMap[t])topicSubjectMap[t]=h.subject;}));
  const allTopics=[...new Set(clean.flatMap(h=>h.wrongTopics||[]))].filter(t=>t&&t!=="Uncategorized");
  const weak=[],improving=[],graduated=[];
  allTopics.forEach(t=>{
    const totalWrong=count(clean,t);
    const recentWrong=count(recent5,t);
    const olderWrong=count(older,t);
    const wasWeak=olderWrong>=2&&older.length>=3;
    if(wasWeak&&recentWrong===0)graduated.push(t);
    else if(recentWrong>=2)weak.push({t,score:recentWrong*3+totalWrong,subject:topicSubjectMap[t]||""});
    else if(recentWrong>=1||totalWrong>=2)improving.push(t);
  });
  weak.sort((a,b)=>b.score-a.score);
  return{weak:weak.slice(0,8),improving:improving.slice(0,4),graduated:graduated.slice(0,3),topicSubjectMap};
}
function calcWeeklyMission(history,weakTopics,readiness,userSubjects=[]) {
  const goal=readiness<65?Math.min(readiness+8,70):Math.min(readiness+5,100);
  const topicStrings=weakTopics.map(x=>typeof x==="string"?x:x.t);
  const tasks=topicStrings.slice(0,2).map(t=>({topic:t,questions:15}));
  // Fallback: suggest practising their weakest subject, never "Mixed Practice"
  if(!tasks.length&&userSubjects.length){
    const subH=userSubjects.map(s=>({s,h:history.filter(h=>h.subject===s)}));
    const leastPractised=subH.sort((a,b)=>a.h.length-b.h.length)[0];
    tasks.push({topic:`${leastPractised.s} Practice`,questions:20});
  }
  const weekStart=new Date();
  weekStart.setDate(weekStart.getDate()-weekStart.getDay());weekStart.setHours(0,0,0,0);
  const thisWeek=history.filter(isRealSession).filter(h=>new Date(h.date)>=weekStart).length;
  return{goal,needed:Math.max(0,goal-readiness),tasks,progress:Math.min(100,Math.round((thisWeek/3)*100)),thisWeek,target:3};
}
// Per-subject topic map: returns each topic seen for a subject with accuracy + JUPEB-threshold colour status
function calcSubjectTopicMap(history,subject) {
  const subHistory=history.filter(h=>h.subject===subject);
  if(!subHistory.length)return[];
  const topicData={};
  subHistory.forEach(h=>{
    (h.questionResults||[]).forEach(r=>{
      if(!r.topic)return;
      if(!topicData[r.topic])topicData[r.topic]={correct:0,total:0};
      topicData[r.topic].total++;
      if(r.correct)topicData[r.topic].correct++;
    });
  });
  return Object.entries(topicData).map(([topic,d])=>{
    const acc=d.total?Math.round((d.correct/d.total)*100):0;
    let status,color,label;
    if(acc>=60){status="strong";color="#4ade80";label="On track";}
    else if(acc>=40){status="needs-work";color="#f97316";label="Needs work";}
    else{status="blocker";color="#ef4444";label="Score blocker";}
    return{topic,accuracy:acc,status,color,label,attempts:d.total};
  }).sort((a,b)=>a.accuracy-b.accuracy);
}
// Find which single topic is most limiting a subject's grade (the "why" explanation)
function findGradeLimiter(history,subject) {
  const map=calcSubjectTopicMap(history,subject);
  const blockers=map.filter(t=>t.status==="blocker"&&t.attempts>=2);
  if(blockers.length)return blockers[0];
  const needsWork=map.filter(t=>t.status==="needs-work"&&t.attempts>=2);
  if(needsWork.length)return needsWork[0];
  return null;
}

// ─── CREDIQ INTELLIGENCE ENGINE ───────────────────────────────────────────────
// Produces a 0-100 Readiness Score, risk level, and target probability
// from existing session history — no AI needed.
function calcReadinessScore(history, user, daysLeft=45) {
  const clean=history.filter(isRealSession);
  if(!clean.length)return{score:0,risk:"CRITICAL",probability:5,avgAccuracy:0,
    consistencyScore:0,improvementScore:50,coverageScore:0,sessionsThisWeek:0,
    totalSessions:0,improvementTrend:"stable"};

  // 1. Recent accuracy (last 5 sessions, weighted heavily)
  const sorted=[...clean].sort((a,b)=>new Date(b.date)-new Date(a.date));
  const recent=sorted.slice(0,5);
  const avgAccuracy=recent.reduce((s,h)=>s+(h.pct||0),0)/recent.length;

  // 2. Consistency — sessions in last 7 days vs target of 5
  const now=Date.now();
  const last7=clean.filter(h=>(now-new Date(h.date))/(1000*60*60*24)<=7);
  const consistencyScore=Math.min(100,(last7.length/5)*100);

  // 3. Improvement trend — compare recent half vs older half
  const half=Math.max(1,Math.floor(sorted.length/2));
  const recentHalf=sorted.slice(0,half);
  const olderHalf=sorted.slice(half);
  const recentAvg=recentHalf.reduce((s,h)=>s+(h.pct||0),0)/recentHalf.length;
  const olderAvg=olderHalf.length?olderHalf.reduce((s,h)=>s+(h.pct||0),0)/olderHalf.length:recentAvg;
  const improvementScore=Math.min(100,Math.max(0,50+(recentAvg-olderAvg)));

  // 4. Coverage — subjects practiced vs subjects enrolled
  const userSubjects=user?.subjects||[];
  const practicedSubjects=[...new Set(clean.map(h=>h.subject).filter(Boolean))];
  const coverageScore=userSubjects.length?Math.min(100,(practicedSubjects.length/userSubjects.length)*100):50;

  // 5. Days pressure factor (less time = lower effective score)
  const daysFactor=Math.max(0.70,Math.min(1,daysLeft/60));

  // Weighted composite
  const raw=(avgAccuracy*0.40+consistencyScore*0.25+improvementScore*0.20+coverageScore*0.15)*daysFactor;
  const score=Math.round(Math.min(100,Math.max(0,raw)));

  // Risk levels
  const risk=score>=75?"LOW":score>=50?"MODERATE":score>=28?"HIGH":"CRITICAL";

  // Probability of reaching target cut-off
  const requiredPoints=user?.requiredPoints||13;
  const rawProb=Math.min(97,Math.max(3,(score/100)*90+(score>70?8:0)-(requiredPoints>15?10:0)));
  const probability=Math.round(rawProb);

  return{
    score,risk,probability,
    avgAccuracy:Math.round(avgAccuracy),
    consistencyScore:Math.round(consistencyScore),
    improvementScore:Math.round(improvementScore),
    coverageScore:Math.round(coverageScore),
    sessionsThisWeek:last7.length,totalSessions:clean.length,
    improvementTrend:recentAvg>olderAvg+2?"up":recentAvg<olderAvg-2?"down":"stable",
    daysLeft,
  };
}

// Rule-based personalized actions — no AI, purely from data
function calcNextActions(history, user, readiness) {
  const actions=[];
  const weakTopics=calcWeakTopics(history);
  const userSubjects=user?.subjects||[];
  const lastSession=history.length?history[history.length-1]:null;
  const daysSinceLast=lastSession
    ?Math.floor((Date.now()-new Date(lastSession.date))/(1000*60*60*24)):999;

  if(daysSinceLast>=3&&daysSinceLast<999)
    actions.push({priority:"urgent",icon:"🔥",
      text:`${daysSinceLast} day${daysSinceLast===1?"":"s"} since your last session. One session now keeps your momentum going.`,
      cta:"Practice Now",action:"practice"});

  if(weakTopics.length>0)
    actions.push({priority:"high",icon:"🎯",
      text:`"${weakTopics[0]}" keeps showing up in your wrong answers. Drill it and close the gap.`,
      cta:"Drill It",action:"drill"});

  if(readiness.consistencyScore<40)
    actions.push({priority:"high",icon:"📅",
      text:`You're averaging ${readiness.sessionsThisWeek}/5 sessions this week. Consistency matters more than cramming at this stage.`,
      cta:"Practice Now",action:"practice"});

  const unpracticed=userSubjects.filter(s=>!history.some(h=>h.subject===s));
  if(unpracticed.length)
    actions.push({priority:"medium",icon:"📚",
      text:`You haven't touched ${unpracticed[0]} yet. Blank subjects are exam-day surprises.`,
      cta:"Start Now",action:"practice"});

  if(readiness.improvementTrend==="down")
    actions.push({priority:"medium",icon:"📉",
      text:"Your accuracy has dropped in recent sessions. Slow down — review before taking more practice tests.",
      cta:"Review Topics",action:"review"});

  if(readiness.score>=75&&actions.length===0)
    actions.push({priority:"positive",icon:"✅",
      text:`You're reading ${readiness.probability}% likely to hit your target. Maintain this pace — ${45-readiness.daysLeft+45} days of consistency wins exams.`,
      cta:"Keep Going",action:"practice"});

  return actions.slice(0,3);
}

// User segmentation for Founder War Room
function segmentUsers(users) {
  const now=Date.now();
  const daysSince=u=>{
    const d=u.lastActiveDate||u.createdAt?.toDate?.()?.toISOString();
    if(!d)return 999;
    try{return Math.floor((now-new Date(d))/86400000);}catch{return 999;}
  };
  const real=users.filter(u=>!u.isTestAccount);
  return{
    likelyToPay:real.filter(u=>!u.isPremium&&(u.totalSessionsCompleted||0)>=3&&daysSince(u)<=7),
    highlyEngaged:real.filter(u=>!u.isPremium&&(u.totalSessionsCompleted||0)>=5),
    inactive:real.filter(u=>!u.isPremium&&(u.totalSessionsCompleted||0)===0&&daysSince(u)>=7),
    stuckOnboarding:real.filter(u=>!u.onboarded),
    needsReactivation:real.filter(u=>u.onboarded&&(u.totalSessionsCompleted||0)>=1&&daysSince(u)>=7&&!u.isPremium),
  };
}

// ─── PENDING SESSIONS — offline backup ────────────────────────────────────────
// Saves session to localStorage before Firestore write.
// If write fails (bad network), data survives and syncs on next load.
const PendingSessions = {
  KEY: "cq_pending_v1",
  push(uid, data) {
    try {
      const all = this.getAll();
      const entry = {id: Date.now(), uid, data};
      all.push(entry);
      localStorage.setItem(this.KEY, JSON.stringify(all.slice(-5))); // keep last 5 max
    } catch(e) {}
  },
  getAll() {
    try { return JSON.parse(localStorage.getItem(this.KEY)||"[]"); } catch { return []; }
  },
  remove(id) {
    try {
      const all = this.getAll().filter(x => x.id !== id);
      localStorage.setItem(this.KEY, JSON.stringify(all));
    } catch(e) {}
  },
  clear() { try { localStorage.removeItem(this.KEY); } catch(e) {} }
};

// ─── FIREBASE HELPERS ─────────────────────────────────────────────────────────
const getUserDoc = async uid => { const s=await getDoc(doc(db,"users",uid)); return s.exists()?s.data():null; };

// ── REFERRAL CREDIT — single source of truth for both redemption paths ─────
// (signup via ?ref= URL, and manually typing a code during onboarding).
// Atomically increments the referrer's referralCount and grants the 3-friend
// (7 days) / 10-friend (permanent) premium unlock exactly once per tier —
// using a transaction so concurrent referrals can't race past a threshold.
const creditReferralSignup = async (rawCode,newUserUid,newUserName)=>{
  const code=(rawCode||"").trim().toUpperCase();
  if(!code)return false;
  try{
    const uq=query(collection(db,"users"),where("referralCode","==",code));
    const uSnap=await getDocs(uq);
    if(uSnap.empty)return false; // not a valid code
    const referrerId=uSnap.docs[0].id;

    // Legacy referrals/{code} doc — best-effort, kept for anything still reading it
    try{
      const signupEntry={uid:newUserUid,name:newUserName||"",date:new Date().toISOString(),isPaid:false};
      await updateDoc(doc(db,"referrals",code),{signups:increment(1),signupsList:arrayUnion(signupEntry)});
    }catch(e){console.warn("Legacy referrals doc update failed:",e);}

    // Source of truth: atomic count + tier unlock
    try{
      await runTransaction(db,async(tx)=>{
        const refDoc=doc(db,"users",referrerId);
        const snap=await tx.get(refDoc);
        const prevCount=snap.data()?.referralCount||0;
        const newCount=prevCount+1;
        const currentUnlock=snap.data()?.referralUnlock;
        const updates={referralCount:increment(1)};
        if(newCount>=3&&currentUnlock!=="permanent"&&currentUnlock!=="7days"){
          updates.isPremium=true;
          updates.premiumExpiry=new Date(Date.now()+7*24*60*60*1000).toISOString();
          updates.referralUnlock="7days";
        }
        if(newCount>=10&&currentUnlock!=="permanent"){
          updates.isPremium=true;
          updates.premiumExpiry=null;
          updates.referralUnlock="permanent";
        }
        tx.update(refDoc,updates);
      });
    }catch(e){
      console.error("Referral tier-unlock transaction failed:",e);
      await updateDoc(doc(db,"users",referrerId),{referralCount:increment(1)}); // don't lose the count even if the tier-check fails
    }

    // Ambassador first-touch attribution — separate system, best-effort
    try{
      await setDoc(doc(db,"ambassadors",code),{code,totalReferrals:increment(1),lastSignup:new Date().toISOString()},{merge:true});
    }catch(e){}

    return true;
  }catch(e){
    console.error("creditReferralSignup error:",e);
    return false;
  }
};

const createUserDoc = async (uid,{name,email,referredBy=null}) => {
  const referralCode=makeRef(uid);
  const data={uid,name,email,course:null,subjects:[],onboarded:false,isPremium:false,questionsToday:0,lastActiveDate:new Date().toDateString(),referralCode,referredBy,referralCount:0,referralBalance:0,weakTopics:[],streak:0,createdAt:serverTimestamp(),
    gradeHistory:[],averageGrade:null,totalSessionsCompleted:0,studyPattern:null,consistencyScore:0,lastSessionDate:null,strongTopics:[],masteryScores:{},examCentreRegion:null,userRole:"student",
  };
  // These two are required — await them
  await setDoc(doc(db,"users",uid),data);
  await setDoc(doc(db,"referrals",referralCode),{uid,name,referralCode,signups:0,conversions:0,earnings:0,createdAt:serverTimestamp()});
  // Credit referrer in background — don't block signup
  if(referredBy){
    creditReferralSignup(referredBy,uid,name).catch(e=>console.error("Referral credit error:",e));
  }
  return data;
};
const saveSession = async (userId,data) => addDoc(collection(db,"sessions"),{userId,...data,createdAt:serverTimestamp()});

// ─── DATA INFRASTRUCTURE v2 ───────────────────────────────────────────────────

// Time helpers
const getTimeOfDay = () => { const h=new Date().getHours(); if(h>=5&&h<12)return"morning"; if(h>=12&&h<17)return"afternoon"; if(h>=17&&h<22)return"evening"; return"night"; };
const getDayOfWeek = () => ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"][new Date().getDay()];
const EXAM_DATE_TARGET = new Date("2026-08-03");
const getDaysToExam = () => Math.max(0,Math.ceil((EXAM_DATE_TARGET-new Date())/(1000*60*60*24)));

// Detect JUPEB course unit (001-004) from topic text
const getCourseUnit = (subject,topic="") => {
  const courses=JUPEB_COURSES[subject];
  if(!courses)return null;
  const t=topic.toLowerCase();
  for(const c of courses){if(c.keywords.some(kw=>t.includes(kw)))return c.code;}
  return courses[0]?.code||null;
};

// Grade to number for averaging
const gradeToNum = g=>({A:90,B:75,C:60,D:50,F:30}[g]||50);
const numToGrade = n=>n>=70?"A":n>=60?"B":n>=50?"C":n>=45?"D":"F";

// Mastery subcollection — users/{uid}/mastery/{topic}
const updateMastery = async (uid,questionResults=[]) => {
  const byTopic={};
  questionResults.forEach(q=>{
    const topic=(q.topic||"General").replace(/[\/\.#\[\]]/g,"_");
    if(!byTopic[topic])byTopic[topic]={correct:0,wrong:0,times:[]};
    if(q.correct)byTopic[topic].correct++;
    else byTopic[topic].wrong++;
    if(q.timeSpent)byTopic[topic].times.push(q.timeSpent);
  });
  const today=new Date().toISOString().split("T")[0];
  await Promise.all(Object.entries(byTopic).map(async([topic,data])=>{
    const ref=doc(db,"users",uid,"mastery",topic);
    const snap=await getDoc(ref);
    const ex=snap.exists()?snap.data():{score:0,attempts:0,correctCount:0,wrongCount:0,history:[]};
    const newCorrect=(ex.correctCount||0)+data.correct;
    const newWrong=(ex.wrongCount||0)+data.wrong;
    const newAttempts=(ex.attempts||0)+data.correct+data.wrong;
    const newScore=newAttempts>0?Math.round((newCorrect/newAttempts)*100):0;
    const avgTime=data.times.length?Math.round(data.times.reduce((a,b)=>a+b,0)/data.times.length):(ex.averageTimeSpent||0);
    const resistanceScore=newAttempts>0?Math.round((newWrong/newAttempts)*100):0;
    const history=[...(ex.history||[]),{date:today,score:newScore}].slice(-30);
    await setDoc(ref,{score:newScore,attempts:newAttempts,correctCount:newCorrect,wrongCount:newWrong,lastUpdated:serverTimestamp(),averageTimeSpent:avgTime,resistanceScore,history});
  }));
};

// Engagement collection — engagement/{uid}
const updateEngagement = async (uid,{timeOfDay,dayOfWeek,streakCount}) => {
  const ref=doc(db,"engagement",uid);
  const snap=await getDoc(ref);
  const ex=snap.exists()?snap.data():{studyTimeDistribution:{morning:0,afternoon:0,evening:0,night:0},weekdayDistribution:{},totalSessions:0,longestStreak:0,crammerScore:0};
  const studyTime={...(ex.studyTimeDistribution||{morning:0,afternoon:0,evening:0,night:0})};
  studyTime[timeOfDay]=(studyTime[timeOfDay]||0)+1;
  const weekday={...(ex.weekdayDistribution||{})};
  weekday[dayOfWeek]=(weekday[dayOfWeek]||0)+1;
  const totalSessions=(ex.totalSessions||0)+1;
  const weeksActive=Math.max(1,Math.ceil(totalSessions/7));
  const averageSessionsPerWeek=Math.round((totalSessions/weeksActive)*10)/10;
  const longestStreak=Math.max(streakCount,ex.longestStreak||0);
  const crammerScore=streakCount>=7?Math.min(100,(ex.crammerScore||0)+5):(ex.crammerScore||0);
  const consistencyScore=Math.min(100,Math.round((streakCount/30)*100));
  await setDoc(ref,{studyTimeDistribution:studyTime,weekdayDistribution:weekday,totalSessions,averageSessionsPerWeek,longestStreak,currentStreak:streakCount,crammerScore,consistencyScore,lastUpdated:serverTimestamp()});
};

// Readiness collection — readiness/{uid}
const updateReadiness = async (uid,allHistory,subjects=[]) => {
  const today=new Date().toISOString().split("T")[0];
  const daysToExam=getDaysToExam();
  const subjectScores={};
  subjects.forEach(sub=>{
    const h=allHistory.filter(x=>x.subject===sub);
    if(h.length)subjectScores[sub]=recentSubjectAccuracy(h);
  });
  const recent=allHistory.slice(-10);
  const overallScore=recent.length?Math.round(recent.reduce((s,h)=>s+h.pct,0)/recent.length):0;
  const predictedGrade=numToGrade(overallScore);
  const recent5=allHistory.slice(-5).map(h=>h.pct);
  const older5=allHistory.slice(-10,-5).map(h=>h.pct);
  const recentAvg=recent5.length?recent5.reduce((a,b)=>a+b,0)/recent5.length:overallScore;
  const olderAvg=older5.length?older5.reduce((a,b)=>a+b,0)/older5.length:overallScore;
  const trend=recentAvg-olderAvg;
  const projectedScore=Math.min(100,Math.round(overallScore+(trend*0.5)));
  const ref=doc(db,"readiness",uid);
  const snap=await getDoc(ref);
  const ex=snap.exists()?snap.data():{readinessHistory:[]};
  const readinessHistory=[...(ex.readinessHistory||[]),{date:today,score:overallScore}].slice(-30);
  await setDoc(ref,{overallScore,predictedGrade,subjectScores,readinessHistory,daysToExam,projectedScoreOnExamDay:projectedScore,lastUpdated:serverTimestamp()});
};
const checkDailyLimit = async (uid,isPremium) => {
  if(isPremium)return{allowed:true,remaining:Infinity};
  const today=new Date().toDateString();
  const snap=await getDoc(doc(db,"users",uid));const d=snap.data();
  if(d.lastActiveDate!==today){
    // Only write if counter needs resetting — avoids wasted write when already 0
    if((d.questionsToday||0)>0){await updateDoc(doc(db,"users",uid),{questionsToday:0,lastActiveDate:today});}
    return{allowed:true,remaining:FREE_DAILY_LIMIT};
  }
  const used=d.questionsToday||0;return{allowed:used<FREE_DAILY_LIMIT,remaining:Math.max(0,FREE_DAILY_LIMIT-used)};
};
const mapErr = code => ({
  "auth/email-already-in-use":"An account with this email already exists.",
  "auth/invalid-email":"That email doesn't look right.",
  "auth/wrong-password":"Incorrect password.",
  "auth/user-not-found":"No account with this email. Sign up instead.",
  "auth/invalid-credential":"Incorrect email or password.",
  "auth/too-many-requests":"Too many attempts. Wait a moment.",
  "auth/weak-password":"Password needs at least 6 characters.",
  "auth/network-request-failed":"No internet. Check your connection.",
})[code]||"Something went wrong. Try again.";

// ─── SHARE CARD COMPONENT ─────────────────────────────────────────────────────
